from __future__ import annotations

import hashlib
import json
import unicodedata
from typing import Final

NFC_FORM: Final[str] = "NFC"

GENESIS: Final[str] = "GENESIS"

_HASH_FIELDS: Final[tuple[str, ...]] = ("hash", "prev_hash")


def normalize_key(key: str) -> str:
    return unicodedata.normalize("NFC", key)


def canonical_bytes(line: dict) -> bytes:
    return json.dumps(
        line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")


def line_hash(prev_hash: str, line: dict) -> str:
    without_hash_fields = {k: v for k, v in line.items() if k not in _HASH_FIELDS}
    payload = prev_hash.encode("utf-8") + b"|" + canonical_bytes(without_hash_fields)
    return hashlib.sha256(payload).hexdigest()

from ledgerlock.cli import main

if __name__ == "__main__":
    raise SystemExit(main())

import json
import unittest

from ledgerlock.format import GENESIS, canonical_bytes, line_hash


class TestCanonicalBytes(unittest.TestCase):
    def test_matches_json_dumps_default(self) -> None:
        line = {"key": "value", "rid": "abc"}
        expected = json.dumps(
            line, sort_keys=True, separators=(",", ":"), ensure_ascii=False
        ).encode("utf-8")
        self.assertEqual(canonical_bytes(line), expected)

    def test_equal_dicts_produce_identical_bytes(self) -> None:
        first = {"rid": "r", "key": "k", "op": "put"}
        second = dict(first)
        self.assertEqual(canonical_bytes(first), canonical_bytes(second))

    def test_non_ascii_uses_utf8_literal(self) -> None:
        line = {"name": "\u00e9"}
        result = canonical_bytes(line)
        self.assertEqual(result, b'{"name":"\xc3\xa9"}')

    def test_byte_stable_across_invocations(self) -> None:
        line = {"name": "\u00e9", "city": "Qu\u00e9bec"}
        first = canonical_bytes(line)
        second = canonical_bytes(line)
        self.assertEqual(first, second)

    def test_key_order_does_not_affect_bytes(self) -> None:
        first = {"a": 1, "b": 2, "c": 3}
        second = {"c": 3, "b": 2, "a": 1}
        self.assertEqual(canonical_bytes(first), canonical_bytes(second))

    def test_round_trip_through_json_loads(self) -> None:
        original = {"rid": "r", "key": "k", "value": 42, "tag": "\u00e9"}
        first = canonical_bytes(original)
        round_tripped = json.loads(first.decode("utf-8"))
        second = canonical_bytes(round_tripped)
        self.assertEqual(first, second)


class TestGenesis(unittest.TestCase):
    def test_genesis_is_seven_char_literal(self) -> None:
        self.assertEqual(GENESIS, "GENESIS")

    def test_genesis_not_a_64_char_hex(self) -> None:
        self.assertNotEqual(len(GENESIS), 64)


class TestLineHash(unittest.TestCase):
    def test_returns_64_lowercase_hex(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        result = line_hash(GENESIS, line)
        self.assertEqual(len(result), 64)
        self.assertTrue(all(c in "0123456789abcdef" for c in result))

    def test_distinct_prev_hash_yields_distinct_digest(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        first = line_hash("aaaa", line)
        second = line_hash("bbbb", line)
        self.assertNotEqual(first, second)

    def test_ignores_existing_hash_and_prev_hash_fields(self) -> None:
        line = {
            "op": "put",
            "key": "k",
            "value": 1,
            "ts": 1,
            "id": "r",
            "hash": "should-be-ignored",
            "prev_hash": "also-ignored",
        }
        expected = line_hash(GENESIS, {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"})
        self.assertEqual(line_hash(GENESIS, line), expected)

    def test_deterministic_across_invocations(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        self.assertEqual(line_hash(GENESIS, line), line_hash(GENESIS, line))

    def test_accepts_genesis_literal_prev_hash(self) -> None:
        line = {"op": "put", "key": "k", "value": 1, "ts": 1, "id": "r"}
        result = line_hash(GENESIS, line)
        self.assertEqual(len(result), 64)


if __name__ == "__main__":
    unittest.main()

